            SELECT id, name, created_at, email
            FROM users
            WHERE active = ${PgTypes.bool(true)}
        """ }
            .query(userCodec.all())

    fun check() {
        val analysis: QueryAnalysis =
            QueryAnalyzer.analyze(query, connection).single()
        if (!analysis.succeeded()) {
            throw AssertionError(analysis.report())
        }
    }
}

