val byPriceRange: Template[Option[(BigDecimal, BigDecimal)], List[Product]] =
  sql"SELECT id, name, price FROM products WHERE 1=1"
    .optionally(
      sql" AND price BETWEEN "
        .param(PgTypes.numeric)
        .append(" AND ")
        .param(PgTypes.numeric))
    .query(productCodec.all())

// With range
