    List(
      Some(byName("%widget%")),
      maxPrice.map(cheaperThan)
    ).flatten

  tx.transact { conn =>
    sql"SELECT * FROM product ${Fragment.whereAnd(filters)}"
      .query(rowCodec.all())
      .run(conn)
  }

// Dynamic UPDATE — only set the fields that changed
def updateUser(userId: Int, newName: Option[String], newEmail: Option[String]): Unit =
  val sets = List(
    newName.map(n => sql"name = ${PgTypes.text(n)}"),
    newEmail.map(e => sql"email = ${PgTypes.text(e)}")
  ).flatten

  if sets.nonEmpty then
    sql"UPDATE users ${Fragment.set(sets)} WHERE id = ${PgTypes.int4(userId)}"
      .update()
      .run(conn)

val query: Fragment =
  sql"""SELECT * FROM users
        WHERE id = ${PgTypes.int4(userId)}
        AND status = ${PgTypes.text("active")}
        AND created_at > ${PgTypes.timestamptz(cutoffDate)}"""

// Parameters are bound, not interpolated
val users: List[User] =
  query.query(userCodec.all()).run(connection)

def cities(): List[City] = tx.transact { conn =>
  findCities.run(conn)
}

// Inner join — both sides always present
val innerJoined: RowCodec[(ProductRow, CategoryRow)] =
  productCodec.joined(categoryCodec)

// Left join — right side is Option
val leftJoined: RowCodec[(ProductRow, Option[CategoryRow])] =
  productCodec.leftJoined(categoryCodec)

// Batch insert — all columns as parameters
val insertAll: RowTemplate.Update[Product] =
  Fragment.insertInto("product", productCodec)

def insertProducts(products: List[Product]): Array[Int] =
  insertAll.onMany(products.iterator).run(conn)

// Batch insert — skip auto-generated ID column
val insertAutoId: RowTemplate.Update[Product] =
  Fragment.insertInto("product", productCodec, "id")

def insertProductsAutoId(products: List[Product]): Array[Int] =
  insertAutoId.onMany(products.iterator).run(conn)

// Fields — discovered automatically
val allCities: Operation[List[City]] =
  Fragment.of("SELECT id, name FROM cities")
    .query(cityCodec.all())

// No-arg methods — discovered automatically
def activeCities(): Operation[List[City]] =
  Fragment.of("SELECT id, name FROM cities WHERE active")
    .query(cityCodec.all())

// Methods with parameters — dummy arguments constructed automatically
def findByName(name: String): Operation[Option[City]] =
  Fragment.of("SELECT id, name FROM cities WHERE name = ")
    .value(PgTypes.text, name)
    .query(cityCodec.maxOne())

// Templates — also discovered
val findById: Template[Int, Option[City]] =
  Fragment.of("SELECT id, name FROM cities WHERE id = ")
    .param(PgTypes.int4)
    .query(cityCodec.maxOne())

